// Multiple classes in one file for a runnable demo.
// In a real project each class lives in its own file.
package com.bank.security;

import java.util.*;
import java.util.logging.*;

public class AuthDemo {
    private static final Logger log = Logger.getLogger(AuthDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AuthenticationService authn = new AuthenticationService();
        AuthorizationService authz = new AuthorizationService();

        try {
            Principal rajesh = authn.authenticate("rajesh", "secret123");
            log.info(() -> "AUTHN OK: identity established for " + rajesh.getUsername());

            authz.checkCanAccessAccount(rajesh, "SAV2001");
            log.info(() -> "AUTHZ OK: " + rajesh.getUsername() + " may access SAV2001");

            authz.checkCanAccessAccount(rajesh, "CUR3001");
        } catch (AuthorizationException e) {
            log.severe("AUTHZ DENIED (403): " + e.getMessage());
        } catch (AuthenticationException e) {
            log.severe("AUTHN FAILED (401): " + e.getMessage());
        }

        try {
            authn.authenticate("rajesh", "wrongpass");
        } catch (AuthenticationException e) {
            log.severe("AUTHN FAILED (401): " + e.getMessage());
        }
    }
}

// ─── Would be in Principal.java ───
class Principal {
    private final String username;
    private final String role;
    Principal(String username, String role) { this.username = username; this.role = role; }
    String getUsername() { return username; }
    String getRole() { return role; }
}

// ─── Would be in AuthenticationException.java ───
class AuthenticationException extends RuntimeException {
    AuthenticationException(String m) { super(m); }
}

// ─── Would be in AuthorizationException.java ───
class AuthorizationException extends RuntimeException {
    AuthorizationException(String m) { super(m); }
}

// ─── Would be in AuthenticationService.java ───
class AuthenticationService {
    // In production: look up bcrypt hash from DB and use passwordEncoder.matches().
    private final Map<String, String> passwords = Map.of("rajesh", "secret123", "priya", "secret456");
    private final Map<String, String> roles = Map.of("rajesh", "CUSTOMER", "priya", "CUSTOMER");

    Principal authenticate(String username, String rawPassword) {
        String stored = passwords.get(username);
        if (stored == null || !stored.equals(rawPassword)) {
            throw new AuthenticationException("Invalid username or password");
        }
        return new Principal(username, roles.get(username));
    }
}

// ─── Would be in AuthorizationService.java ───
class AuthorizationService {
    private final Map<String, String> accountOwner = Map.of("SAV2001", "rajesh", "CUR3001", "priya");

    void checkCanAccessAccount(Principal p, String accountId) {
        String owner = accountOwner.get(accountId);
        boolean isOwner = p.getUsername().equals(owner);
        boolean isTeller = "TELLER".equals(p.getRole());
        if (!isOwner && !isTeller) {
            throw new AuthorizationException(
                p.getUsername() + " is not allowed to access account " + accountId);
        }
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
            r.getMillis(), r.getLevel().getName(),
            r.getSourceClassName() == null ? "Unknown"
                : r.getSourceClassName().substring(r.getSourceClassName().lastIndexOf('.') + 1),
            r.getMessage());
    }
}
